INSERT INTO `Stay` VALUES (40,5,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,1,'2025-08-29 08:01:24',NULL,NULL,'전남 구례군 산동면 가람마을','127-1','가람마을 별채 1호','전기가 아닌 진짜 온돌집\n집근처에 맹꽁이가 아름답게 울음'),(38,4,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,2,'2025-08-29 08:01:24',NULL,NULL,'전남 구례군 산동면 가람마을','128-2','가람마을 별채 2호','옛 한옥을 개조한 숙소\n마을 어르신과 함께하는 아침 밥상'),(42,6,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,3,'2025-08-29 08:01:24',NULL,NULL,'전북 순창군 구림면 나루마을','52-3','나루마을 별채 1호','강가 풍경이 한눈에 보이는 집\n밤마다 개구리 합창'),(40,5,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,4,'2025-08-29 08:01:24',NULL,NULL,'전북 순창군 구림면 나루마을','53-5','나루마을 별채 2호','전통 기와지붕 한옥\n정원에 감나무가 있어 가을이면 주렁주렁'),(36,4,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,5,'2025-08-29 08:01:24',NULL,NULL,'전북 장수군 번암면 머루마을','11-7','머루마을 별채 1호','머루 포도향이 가득한 시골집\n넓은 마당에서 바비큐 가능'),(45,6,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,6,'2025-08-29 08:01:24',NULL,NULL,'전북 장수군 번암면 머루마을','12-9','머루마을 별채 2호','구들방의 훈훈함을 그대로\n산자락에 위치해 조용한 휴식 가능'),(39,5,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,7,'2025-08-29 08:01:24',NULL,NULL,'경북 영덕군 강구면 솔향마을','201-1','솔향마을 별채 1호','바닷바람이 솔숲을 스쳐가는 집\n갯내음과 솔향이 어우러진다.'),(37,4,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,8,'2025-08-29 08:01:24',NULL,NULL,'경북 영덕군 강구면 솔향마을','201-2','솔향마을 별채 2호','고즈넉한 솔숲 옆 작은 한옥\n밤에는 파도소리가 들린다.'),(41,6,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,9,'2025-08-29 08:01:24',NULL,NULL,'경남 산청군 금서면 달빛마을','88-4','달빛마을 별채 1호','달빛이 잘 비치는 마당\n밤하늘 별구경 명소'),(40,5,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,10,'2025-08-29 08:01:24',NULL,NULL,'경남 산청군 금서면 달빛마을','88-5','달빛마을 별채 2호','계곡물 소리가 들리는 집\n여름철 피서지로 안성맞춤'),(35,4,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,11,'2025-08-29 08:01:24',NULL,NULL,'전남 곡성군 오산면 청솔마을','301-6','청솔마을 별채 1호','마당에 소나무가 우거져 있어 사계절 내내 푸르름을 자랑한다.'),(44,6,_binary '',_binary '\0','2025-08-29 07:46:40',NULL,12,'2025-08-29 08:01:24',NULL,NULL,'전남 곡성군 오산면 청솔마을','301-7','청솔마을 별채 2호','넓은 사랑방과 온돌방이 있는 전통 가옥\